#!/usr/bin/env python3
# WP-N1 docs-konsolidering (lead). Kjøres i n1-worktreen. Idempotent: avbryter hvis D-477 finnes.
import re, sys, pathlib
ROOT = pathlib.Path(sys.argv[1])
SUITE_FINAL = sys.argv[2] if len(sys.argv) > 2 else "@@SUITE_FINAL@@"
DELTA2 = sys.argv[3] if len(sys.argv) > 3 else "@@DELTA2@@"

def rd(p): return (ROOT / p).read_text(encoding="utf-8")
def wr(p, s): (ROOT / p).write_text(s, encoding="utf-8")
def sub1(s, old, new, label):
    n = s.count(old)
    if n != 1: raise SystemExit(f"FEIL: {label}: forventet 1 treff, fant {n}")
    return s.replace(old, new)

